import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
    best = 0

    def dfs(i, j, acc):
        nonlocal best
        v = g[i][j]
        g[i][j] = 0
        acc += v
        if acc > best:
            best = acc
        if i > 0 and g[i - 1][j]:
            dfs(i - 1, j, acc)
        if i + 1 < r and g[i + 1][j]:
            dfs(i + 1, j, acc)
        if j > 0 and g[i][j - 1]:
            dfs(i, j - 1, acc)
        if j + 1 < c and g[i][j + 1]:
            dfs(i, j + 1, acc)
        g[i][j] = v

    for i in range(r):
        for j in range(c):
            if g[i][j]:
                dfs(i, j, 0)
    print(best)

main()

