import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
cells = [(i, j) for i in range(r) for j in range(c) if g[i][j] > 0]
idx = {p: k for k, p in enumerate(cells)}
best = 0
# breadth-first over (visited mask, current cell) states
frontier = {(1 << k, k) for k in range(len(cells))}
total = {}
for mask, k in frontier:
    total[(mask, k)] = g[cells[k][0]][cells[k][1]]
while frontier:
    nxt = set()
    for mask, k in frontier:
        s = total[(mask, k)]
        best = max(best, s)
        i, j = cells[k]
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            q = (i + di, j + dj)
            if q in idx and not (mask >> idx[q]) & 1:
                st = (mask | (1 << idx[q]), idx[q])
                total[st] = s + g[q[0]][q[1]]
                nxt.add(st)
    frontier = nxt
print(best)

